from fractions import Fraction
from typing import Sequence

def regret(probabilities: Sequence[Fraction], strategy: Sequence[bool]) -> Fraction:
    if len(probabilities) != len(strategy):
        raise ValueError("length mismatch")
    return sum((2*abs(2*q-1) for q, s in zip(probabilities, strategy)
                if s != (q >= Fraction(1,2))), Fraction(0))

q = [Fraction(1,2), Fraction(2,3), Fraction(1,4), Fraction(9,10), Fraction(0)]
print(regret(q, [False, True, True, True, False]))

from fractions import Fraction
from typing import Sequence

def total(strategy: Sequence[bool], world: Sequence[bool]) -> int:
    return sum(1 if s == t else -1 for s, t in zip(strategy, world))

def mixed(weights: Sequence[Fraction], strategies: Sequence[Sequence[bool]],
          world: Sequence[bool]) -> Fraction:
    return sum((w*total(s, world) for w, s in zip(weights, strategies)), Fraction(0))

def witness(weights: Sequence[Fraction], strategies: Sequence[Sequence[bool]],
            world: Sequence[bool]) -> tuple[bool, ...]:
    world_tuple = tuple(world)
    return world_tuple if mixed(weights, strategies, world_tuple) <= 0 else tuple(not x for x in world_tuple)

weights = [Fraction(1,2), Fraction(1,3), Fraction(1,6)]
strategies = [(True,True,False,False), (False,True,True,False), (True,False,True,True)]
print(witness(weights, strategies, (True,False,False,True)))

